-- =============================================================================
-- The extracted corpus, one wide table per record family.
--
-- Generated by src.flatten.pivot_wide from the extraction field list and the
-- published facts; edit the module, never this file. One row is one printed
-- table row (split by column label where a table's columns are entities), and
-- one column is one vocabulary name: the family's preferred names first, then
-- any other name the facts carry in it. Numeric columns hold the value as printed
-- with the row's scale heading beside it, not multiplied in. Every row lists
-- the observation IDs it came from, and bridge_pivot_observation carries the
-- same link with a foreign key to fact_observation.
--
-- Loads after 03_extracted_star_ddl.sql into data/warehouse/extracted.duckdb.
-- =============================================================================

-- A printed portfolio allocation amount or percentage.
-- Grain of the source family: one populated allowed source value cell for one allocation bucket.
CREATE TABLE IF NOT EXISTS wide_allocation_observation (
    "wide_row_id"                  VARCHAR NOT NULL,
    "document_id"                  VARCHAR NOT NULL,
    "route"                        VARCHAR,
    "canonical_doc_type"           VARCHAR,
    "page_id"                      VARCHAR NOT NULL,
    "source_page"                  VARCHAR,
    "source_section"               VARCHAR,
    "source_table"                 VARCHAR,
    "source_row_label"             VARCHAR,
    "source_occurrence"            INTEGER,
    "column_group"                 VARCHAR,
    "subject_type"                 VARCHAR,
    "subject_alias_id"             VARCHAR,
    "subject_entity_id"            VARCHAR,
    "subject_name"                 VARCHAR,
    "subject_standardized_name"    VARCHAR,
    "subject_manager_name"         VARCHAR,
    "asset_class"                  VARCHAR,
    "strategy"                     VARCHAR,
    "geography"                    VARCHAR,
    "vintage_year"                 VARCHAR,
    "horizon"                      VARCHAR,
    "as_of_date_raw"               VARCHAR,
    "as_of_date"                   DATE,
    "period_start"                 DATE,
    "period_end"                   DATE,
    "currency"                     VARCHAR,
    "unit_scale"                   VARCHAR,
    "unit_scale_multiplier"        DECIMAL(20, 2),
    "actual_allocation"            DECIMAL(30, 6),
    "target_allocation"            DECIMAL(30, 6),
    "market_value"                 DECIMAL(30, 6),
    "observation_ids"              VARCHAR NOT NULL,
    "observation_count"            INTEGER,
    "unparsed_values"              VARCHAR,
    "scale_note"                   VARCHAR,
    "collision_note"               VARCHAR,
    PRIMARY KEY ("wide_row_id"),
    FOREIGN KEY ("document_id") REFERENCES dim_document(document_id),
    FOREIGN KEY ("page_id") REFERENCES dim_page(page_id),
    FOREIGN KEY ("subject_alias_id") REFERENCES entity_alias(alias_id),
    FOREIGN KEY ("subject_entity_id") REFERENCES dim_entity(entity_id)
);

